def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not points:
        return [row[:] for row in grid]

    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)

    counts = {}
    for r, c in points:
        counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    frame = max(counts, key=counts.get)
    other = [color for color in counts if color != frame]
    if not other:
        return [row[:] for row in grid]
    fill = max(other, key=lambda color: counts[color])
    core = [(r, c) for r, c in points if grid[r][c] == fill]

    # The interior motif grows outward as a halo; a single-cell motif makes
    # a one-cell halo, while a larger motif makes a two-cell halo.
    expansion = 1 if len(core) == 1 else 2

    out = [row[:] for row in grid]
    for r in range(max(0, r0 - expansion), min(h, r1 + expansion + 1)):
        for c in range(max(0, c0 - expansion), min(w, c1 + expansion + 1)):
            if r < r0 or r > r1 or c < c0 or c > c1:
                out[r][c] = fill
    return out
